INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q3921576', 'First Battle of Agordat', 'The First Battle of Agordat, which took place on 27 June 1890 was the first battle between Italy and the Mahdist State.', 1890, 6, 27, NULL, NULL, NULL, 'day', '27 June 1890', 39, 'https://en.wikipedia.org/wiki/First_Battle_of_Agordat'),
  ('Q665983', 'Second Battle of Agordat', 'The Second Battle of Agordat was fought in late December 1893, between Italian colonial troops and Mahdists from Sudan. Emir Ahmed Ali campaigned against the Italian forces in eastern Sudan and led about 10,000–12,000 men east from Kassala.', 1893, 12, 21, NULL, NULL, NULL, 'day', '21 December 1893', 37, 'https://en.wikipedia.org/wiki/Second_Battle_of_Agordat'),
  ('Q989115', 'First Italo-Ethiopian War', 'The First Italo-Ethiopian War, also referred to as the First Italo-Abyssinian War, or simply known as the Abyssinian War in Italy (Italian: Guerra d''Abissinia), was fought between Italy and Ethiopia from 1895 to 1896. It originated from the disputed Treaty of Wuchale, which the Italians claimed turned Ethiopia into an Italian protectorate, while the Ethiopians claimed that the treaty simply ensured peace between the two powers.', 1894, 12, 15, 1896, 10, 23, 'day', '15 December 1894 – 23 October 1896', 73, 'https://en.wikipedia.org/wiki/First_Italo-Ethiopian_War'),
  ('Q2888324', 'Battle of Coatit', 'The Battle of Coatit was fought on 13 January 1895 between Italy and Ethiopian proxies led by Tigrayan Prince Ras Mengesha Yohannes in what is now Eritrea. It was the opening battle of the First Italo–Ethiopian War, and was a significant victory for the Italians, as they rebuffed an invasion force.', 1895, 1, 13, NULL, NULL, NULL, 'day', '13 January 1895', 47, 'https://en.wikipedia.org/wiki/Battle_of_Coatit'),
  ('Q4560013', '1915 Asmara earthquake', 'The 1915 Asmara earthquake took place outside Asmara, Eritrea on September 23 with an Mw of 6.2 and a maximum perceived intensity of VI (Strong) on the Mercalli intensity scale.', 1915, 9, 23, NULL, NULL, NULL, 'day', '23 September 1915', 34, 'https://en.wikipedia.org/wiki/1915_Asmara_earthquake'),
  ('Q2330932', '1921 Massawa earthquake', 'The 1921 Massawa earthquake took place off the coast of Massawa, Eritrea, on August 14 with a moment magnitude of 6.1 and a Mercalli intensity of VIII (Severe). The first aftershock after the initial earthquake was of similar magnitude.', 1921, 8, 14, NULL, NULL, NULL, 'day', '14 August 1921', 39, 'https://en.wikipedia.org/wiki/1921_Massawa_earthquake'),
  ('Q1970005', 'Battle of Keren', 'The Battle of Keren (Italian: Battaglia di Cheren) took place from 3 February to 27 March 1941. Keren was attacked by the British during the East African Campaign of the Second World War.', 1941, 2, 5, 1941, 4, 1, 'day', '5 February 1941 – 1 April 1941', 55, 'https://en.wikipedia.org/wiki/Battle_of_Keren'),
  ('Q3636314', 'Battle of Agordat', 'The Battle of Agordat was fought near Agordat in Eritrea from 26 to 31 January 1941, by the Italian army and Royal Corps of Colonial Troops against British, Commonwealth and Indian forces, during the East African Campaign of the Second World War. The British had the advantage of breaking Italian codes and cyphers before the offensive and received copious amounts of information from Italian sources on the order of battle and plans of the Regia Aeronautica (Italian Royal Air Force) and the Italian army.', 1941, 1, 26, 1941, 1, 31, 'day', '26 January 1941 – 31 January 1941', 41, 'https://en.wikipedia.org/wiki/Battle_of_Agordat_(1941)'),
  ('Q2139988', 'Eritrean Civil Wars', 'The Eritrean Civil Wars were two conflicts that were fought between competing organizations for the liberation of Eritrea. The First Eritrean Civil War was fought from 1972 to 1974.', 1974, 10, 13, NULL, NULL, NULL, 'day', '13 October 1974', 41, 'https://en.wikipedia.org/wiki/Eritrean_Civil_Wars'),
  ('Q4337360', 'Siege of Barentu', 'The siege of Barentu took place in 1977 in and around the town of Barentu. It was jointly laid to siege by the Eritrean Liberation Front (ELF) and the Eritrean People''s Liberation Front (EPLF) against the forces of Ethiopia.', 1977, 5, 5, 1977, NULL, NULL, 'day', '1977', 34, 'https://en.wikipedia.org/wiki/Siege_of_Barentu'),
  ('Q4349238', 'Battle of Massawa', 'The First Battle of Massawa took place from 1977 to 1978 in and around the coastal city of Massawa. The port was besieged by the Eritrean People''s Liberation Front (EPLF) against the forces of Ethiopia and was one of two battles in and around the city.', 1977, NULL, NULL, 1978, NULL, NULL, 'year', '1977–1978', 34, 'https://en.wikipedia.org/wiki/First_Battle_of_Massawa'),
  ('Q4128027', 'Battle of Massawa', 'The Second Battle of Massawa (also known as Operation Fenkil and as the Fenkil offensive) took place in 1990 in and around the coastal city of Massawa. The offensive was conducted by both land and sea units of the Eritrean People''s Liberation Front (EPLF) against the Ethiopian Army and resulted in the destruction of the Ethiopian 606th Corps.', 1990, NULL, NULL, 1990, 2, 10, 'year', '1990', 34, 'https://en.wikipedia.org/wiki/Second_Battle_of_Massawa'),
  ('Q832273', 'Eritrean–Ethiopian War', 'The Eritrean–Ethiopian War, also known as the Badme War, was a major armed conflict between Ethiopia and Eritrea that took place from May 6, 1998 to June 18, 2000. After Eritrea gained independence from Ethiopia in 1993, relations were initially friendly.', 2000, 6, 18, 2000, 5, 25, 'day', '18 June 2000 – 25 May 2000', 70, 'https://en.wikipedia.org/wiki/Eritrean%E2%80%93Ethiopian_War'),
  ('Q1354920', 'Djiboutian–Eritrean border conflict', 'The Djiboutian–Eritrean border conflict was a border conflict between the forces of Djibouti and Eritrea that occurred between June 10 and June 13, 2008. It was triggered by tension which began on April 16, 2008, when Djibouti reported that Eritrean armed forces had penetrated into Djibouti and dug trenches on both sides of the border.', 2008, NULL, NULL, 2008, 6, 13, 'year', '2008', 57, 'https://en.wikipedia.org/wiki/Djiboutian%E2%80%93Eritrean_border_conflict'),
  ('Q106959326', 'Ethiopian civil conflict (2018–present)', 'The Ethiopian civil conflict is a series of armed conflicts in Ethiopia that have been ongoing since 2018. In November 2019, three of the four constituent parties of the ruling Ethiopian People''s Revolutionary Democratic Front (EPRDF) approved a merger into the Prosperity Party, while the Tigray People''s Liberation Front (TPLF) opposed the move.', 2018, 4, 2, NULL, NULL, NULL, 'day', '2 April 2018', 45, 'https://en.wikipedia.org/wiki/Ethiopian_civil_conflict_(2018%E2%80%93present)'),
  ('Q141671500', '2026 Eritrean invasion of Ethiopia', 'During the 2026 Ethiopian Offensive, sometime between 28 September and 6 October 2026 (inclusive), the Eritrean Army, which had remained present in Tigray Region in Ethiopia following the Tigray war, were reportedly deployed to several locations in Tigray before pulling back after drone strikes. Ethiopian authorities described the event as an invasion and Eritrean authorities described Ethiopia''s threats to invade Eritrean ports and coastal areas as a declaration of war.', 2026, 10, 6, NULL, NULL, NULL, 'day', '6 October 2026', 30, 'https://en.wikipedia.org/wiki/2026_Eritrean_incursion_into_Ethiopia');
